import {World,Runner,START} from './core.js';
import {missions,STAGES,judge,trials} from './missions.js';
import {createEditor} from './blocks.js';
import {createSimulator} from './simulator.js';
import {hardwareStatus} from './hardware.js';
const $=id=>document.getElementById(id),safeGet=k=>{try{return localStorage.getItem(k);}catch{return null;}},safeSet=(k,v)=>{try{localStorage.setItem(k,v);return true;}catch{return false;}};
let completed=new Set();try{completed=new Set(JSON.parse(safeGet('clms2-completed')||'[]').filter(x=>Number.isInteger(x)&&x>=1&&x<=26));}catch{}
let active=missions[0],world=new World(active),simulator,runner,editor,hint=0,busy=false,aborted=false,trialPass=false,resetArmed=0,clearArmed=0;
let editorLoaded=false; let savedTimer;const key=()=>`clms2-workspace-${active.id}`;
const status=text=>{$('status').textContent=text;};
function persist(){if(!editor)return;const ok=safeSet(key(),editor.save());$('save').textContent=ok?'이 기기에 저장됨':'저장 공간 사용 불가 · 파일로 저장하세요';}
function changed(){clearTimeout(savedTimer);trialPass=false;$('save').textContent='편집 중';$('block-count').textContent=editor.count()+' 블록';savedTimer=setTimeout(persist,450);}
function drawProgress(){const n=[...completed].filter(x=>x<=24).length;$('completion').textContent=n+' / 24';$('progress').value=n;for(const option of $('mission').options){const m=missions[Number(option.value)-1];option.textContent=(completed.has(m.id)?'✓ ':'')+String(m.id).padStart(2,'0')+' · '+m.title;}drawGrid();}
function drawGrid(){const root=$('mission-grid');root.replaceChildren();for(const [s,name] of STAGES.entries()){const section=document.createElement('section'),h=document.createElement('h3'),cards=document.createElement('div');cards.className='cards';h.textContent=(s+1)+'단계 · '+name;section.append(h,cards);for(const m of missions.filter(x=>x.stage===s)){const button=document.createElement('button');button.className='mission-card'+(completed.has(m.id)?' done':'')+(active.id===m.id?' active':'');const number=document.createElement('span'),text=document.createElement('div'),b=document.createElement('b'),small=document.createElement('small');number.textContent=completed.has(m.id)?'✓':String(m.id).padStart(2,'0');b.textContent=m.title;small.textContent='★'.repeat(m.difficulty)+' · '+m.minutes+'분';text.append(b,small);button.append(number,text);button.onclick=()=>{if(busy)return;openMission(m.id);$('missions-dialog').close();};cards.append(button);}root.append(section);}}
function draw(){simulator?.update(world);$('angles').replaceChildren(...Object.entries(world.pose).map(([k,v],i)=>{const el=document.createElement('span');el.innerHTML=['베이스','하완','상완','그리퍼'][i]+'<b>'+Math.round(v)+'°</b><small>'+['D6 · 10~170°','D9 · 30~170°','D10 · 10~160°','D11 · 50~120°'][i]+'</small>';return el;}));$('distance').value=world.sensor;$('cm').value=world.sensor+' cm';$('timer').textContent=String(Math.floor(world.elapsed/60000)).padStart(2,'0')+':'+String(Math.floor(world.elapsed/1000)%60).padStart(2,'0');
 $('cargo').replaceChildren(...(world.cubes.length?world.cubes.map(c=>{const el=document.createElement('span');el.className='cube-chip '+c.color;el.textContent=['빨강','초록','파랑'][c.id%3]+(active.id===22&&c.defect?' (불량)':'')+' · '+(c.station==='held'?'집는 중':c.station==='floor'?'바닥':c.station+' 작업대');return el;}):[Object.assign(document.createElement('span'),{textContent:'관절과 센서를 먼저 연습해 보세요.'})]));
 $('event-count').textContent=world.events.length;const names={pick:'큐브 집기',release:'큐브 내려놓기',read:'초음파 읽기',sensor:'가상 거리 설정',branch:'거리 조건 선택',stop:'실행 정지',wait:'기다리기'};$('log').replaceChildren(...world.events.filter(x=>names[x.type]).slice(-30).map(e=>{const li=document.createElement('li');li.textContent=names[e.type]+(e.station?' → '+e.station:'')+(e.value!==undefined?' · '+e.value+'cm':'')+(e.id!==undefined?' · 큐브 '+(e.id+1):'');return li;}));
}
function makeRunner(){runner=new Runner(world,{animate:async()=>draw(),onStep:id=>editor.highlight(id)});}
function lock(value){busy=value;for(const id of ['run','mission','all-missions','clear','import','judge','custom-target'])$(id).disabled=value;document.querySelectorAll('[data-block]').forEach(b=>b.disabled=value);$('stop').disabled=!value;editor.lock(value);}
function resetWorld(sensor=40){runner?.stop();world=new World(active);world.sensor=sensor;makeRunner();trialPass=false;draw();}
function openMission(id){if(busy)return;clearTimeout(savedTimer);if(editorLoaded)persist();active=missions.find(m=>m.id===id)||missions[0];hint=0;resetArmed=clearArmed=0;$('hint').textContent='💡 힌트 0 / 3';$('hint-text').hidden=true;$('mission').value=active.id;$('stage-label').textContent=String(active.stage+1).padStart(2,'0')+' / '+STAGES[active.stage];$('title').textContent=String(active.id).padStart(2,'0')+' · '+active.title;$('meta').textContent='★'.repeat(active.difficulty)+' · 예상 '+active.minutes+'분'+(active.id>24?' · 빠른 학생을 위한 추가 도전':'');$('goal').textContent=$('criteria').textContent=active.goal;$('initial').textContent=active.initial;$('custom-wrap').hidden=active.id!==24;editor.load(safeGet(key()));editorLoaded=true;$('block-count').textContent=editor.count()+' 블록';resetWorld(active.id===15?10:40);status('블록을 연결해 목표에 도전하세요. 실행하면 시작 상태로 돌아갑니다.');drawGrid();}
function assess(){if(trials(active).length>1&&!trialPass)return {pass:false,message:'두 센서 입력을 모두 검사해야 합니다. 실행 버튼으로 전체 검사를 완료하세요.'};return judge(world,{blocks:editor.count(),customTarget:$('custom-target').value});}
function celebrate(result){status(result.message);if(!result.pass)return;const first=!completed.has(active.id);completed.add(active.id);safeSet('clms2-completed',JSON.stringify([...completed]));drawProgress();$('result-text').textContent=active.title+' · '+(first?'첫 성공을 기록했어요!':'다시 성공했어요! 점수는 미션당 한 번만 합산됩니다.');$('result').querySelector('.score').innerHTML=(first?'+100':'완료')+' <small>누적 '+completed.size*100+' POINTS</small>';$('result').showModal();}
for(const m of missions){const option=new Option('',m.id);$('mission').add(option);}editor=createEditor($('workspace'),changed);drawProgress();
$('mission').onchange=()=>openMission(Number($('mission').value));$('all-missions').onclick=()=>{$('missions-dialog').showModal();};
document.querySelectorAll('[data-block]').forEach(b=>b.onclick=()=>{if(!busy)editor.insert(b.dataset.block);});
$('hint').onclick=()=>{hint=Math.min(3,hint+1);$('hint').textContent='💡 힌트 '+hint+' / 3';$('hint-text').hidden=false;$('hint-text').textContent=active.hints.slice(0,hint).map((s,i)=>(i+1)+'. '+s).join(' ');};
$('run').onclick=async()=>{if(busy||!simulator)return;let program;try{program=editor.program();}catch(e){status(e.message);return;}clearTimeout(savedTimer);persist();aborted=false;lock(true);trialPass=false;let all=true;
 try{for(const [i,value] of trials(active).entries()){if(aborted)return;resetWorld(value);status(trials(active).length>1?`입력 검사 ${i+1}/2 · ${value}cm 실행 중`:'실행 중 · 노란 집기 중심과 큐브 위치를 살펴보세요.');await runner.run(program);if(aborted)return;draw();const result=judge(world,{blocks:editor.count(),customTarget:$('custom-target').value});if(!result.pass){all=false;status((trials(active).length>1?`${value}cm 검사 실패 · `:'')+result.message);break;}}
  if(all){trialPass=true;celebrate(judge(world,{blocks:editor.count(),customTarget:$('custom-target').value}));}
 }catch(e){status('실행을 멈췄어요. '+e.message);}finally{lock(false);editor.highlight(null);draw();}
};
$('stop').onclick=()=>{aborted=true;runner.stop();trialPass=false;draw();status('실행 정지 · 현재 자세를 유지합니다. 초기화로 다시 시작할 수 있어요.');};
$('reset').onclick=()=>{if(busy){aborted=true;runner.stop();status('정지 요청 · 현재 동작을 멈추고 있습니다. 다시 초기화를 누르세요.');return;}resetWorld(active.id===15?10:40);status('재도전 준비 완료 · 코드와 완료 기록은 유지됩니다.');};
$('judge').onclick=()=>celebrate(assess());$('camera').onclick=()=>simulator?.resetCamera();
$('distance').oninput=()=>{world.sensor=Number($('distance').value);draw();};
$('custom-target').onchange=()=>{trialPass=false;status('내 목적지가 '+$('custom-target').value+'로 바뀌었습니다. 다시 실행하세요.');};
$('clear').onclick=()=>{if(Date.now()>clearArmed){clearArmed=Date.now()+4000;status('현재 미션 코드를 지우려면 4초 안에 코드 처음부터를 한 번 더 누르세요.');return;}editor.load('');persist();resetWorld();status('시작하기 블록만 남겼습니다.');clearArmed=0;};
$('export').onclick=()=>{persist();const blob=new Blob([JSON.stringify({format:'CubeLinkMission2',mission:active.id,xml:editor.save()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='CubeLink-Mission-'+active.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{if(file.size>1000000)throw Error('파일은 1MB 이하여야 합니다.');const data=JSON.parse(await file.text());if(data.format!=='CubeLinkMission2'||typeof data.xml!=='string'||data.mission!==active.id)throw Error('현재 미션의 CubeLink 2.0 저장 파일을 선택하세요.');const xml=new DOMParser().parseFromString(data.xml,'text/xml');if(xml.querySelector('parsererror')||[...xml.querySelectorAll('block,shadow')].some(b=>!b.getAttribute('type')?.startsWith('ms_')))throw Error('올바르지 않은 블록 파일입니다.');const backup=editor.save();try{editor.load(data.xml);}catch(e){editor.load(backup);throw e;}persist();resetWorld();status('현재 미션 코드를 불러왔습니다.');}catch(e){status(e.message);}$('file').value='';};
function info(title,html){$('info-title').textContent=title;$('info-body').innerHTML=html;$('info-dialog').showModal();}
$('hardware').onclick=()=>info('실물 로봇팔 · 검증 대기',`<p>${hardwareStatus.reason}</p><p>기존 펌웨어의 서보 명령과 초기화·저장자세 규격은 확인했습니다. 실제 장비 없이 연결·안전 정지 완료로 표시하지 않습니다.</p><p>현재 웹앱의 실행·정지는 가상 로봇팔에만 적용됩니다. 실물 실습은 교사가 검증한 CubeLink Studio로 진행하세요. 이 웹앱의 미션 성공은 가상 결과입니다.</p><table><tr><th>관절</th><th>핀</th><th>제한</th></tr><tr><td>베이스</td><td>D6</td><td>10~170°</td></tr><tr><td>하완</td><td>D9</td><td>30~170°</td></tr><tr><td>상완</td><td>D10</td><td>10~160°</td></tr><tr><td>그리퍼</td><td>D11</td><td>50~120°</td></tr></table><p>모델 축·부품은 기존 CubeLink 자료를 사용했습니다. 관절 기구학은 모델 좌표 기준이며 실제 치수 오차와 충돌·힘·미끄러짐은 재현하지 않습니다. 작업대 이동은 시뮬레이션 학습용 보조 블록입니다.</p>`);
$('classroom').onclick=()=>info('안산공고 · 180분 수업',`<p>학생 20명 이상 · 가능하면 1인 1대. 처음에는 장비 없이 가상 실습을 진행합니다. 24개는 전체 미션 은행이며, 모든 학생이 180분 안에 전부 끝내는 것을 필수로 하지 않습니다.</p><table><tr><th>시간</th><th>활동</th></tr><tr><td>0~25분</td><td>구조·4관절·집기·전원 안전 이론</td></tr><tr><td>25~85분</td><td>가상 블록 코딩 · 미션 1~12 (기본 1~8, 선택 9~12)</td></tr><tr><td>85~95분</td><td>실제 로봇팔 배포 · 코드 파일 저장</td></tr><tr><td>95~110분</td><td>교사 검증 장비 연결·시작자세·한 관절씩 점검</td></tr><tr><td>110~160분</td><td>실물 제어 · 13~18 센서·반복 원리 적용, 미션 8 운반 재현</td></tr><tr><td>160~180분</td><td>19~24 중 최종 과제 선택 · 결과 공유·장비 정리</td></tr></table><p>13~24와 추가 도전은 가상으로 계속 연습할 수 있습니다. 실제 장비 제어와 실물 성과 확인은 검증된 기존 Studio 및 교사 관찰로 진행하며 이 웹앱은 실물 자동 판정을 하지 않습니다.</p><p>진도와 코드는 이 브라우저에 저장됩니다. 공용 기기 사용 전 개별 파일로 저장하세요. 학급 전체 진도 서버 수집 기능은 없습니다.</p>`);
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('next').onclick=()=>{$('result').close();openMission(active.id===26?1:active.id+1);};
window.addEventListener('beforeunload',()=>persist());
openMission(1);
try{simulator=await createSimulator($('robot'));$('loading').remove();draw();$('run').disabled=false;status('3D 준비 완료 · 첫 미션은 베이스 60° → 120° → 90°입니다.');}catch(e){status('3D를 시작할 수 없습니다. WebGL 사용 가능 여부를 확인하세요. '+e.message);$('loading').textContent='3D 로딩 실패 · 실행 기능을 잠갔습니다.';}
